import pytest

from bedrock_protocol import v975, v1001, v2168, v2193, v2225

# generated by gophertunnel 6353c49:
# &packet.ClientboundUpdateSoundData{ServerSoundHandle: 42, SoundEvent: "Stop"}
V1001_STOP = bytes.fromhex("2a000000000000000473746f70")

# generated by gophertunnel b8bd735:
# &packet.ClientboundUpdateSoundData{ServerSoundHandle: 42, Stop: u, SetVolume: u, SetPitch: u, Fade: u,
#     SeekTo: u, Pause: u, Resume: u} with u := protocol.SoundDataUpdate{Type: protocol.SoundDataUpdateSetVolume,
#     Volume: 0.5}
V2193_VOLUME = bytes.fromhex("2a00000000000000010000003f010000003f010000003f010000003f010000003f010000003f010000003f")

# generated by gophertunnel b8bd735:
# &packet.ClientboundUpdateSoundData{ServerSoundHandle: 42, Stop: u, SetVolume: u, SetPitch: u, Fade: u,
#     SeekTo: u, Pause: u, Resume: u} with u := protocol.SoundDataUpdate{Type: protocol.SoundDataUpdateFade,
#     Duration: 1.5, TargetVolume: 0.25}
V2193_FADE = bytes.fromhex(
    "2a00000000000000030000c03f0000803e030000c03f0000803e030000c03f0000803e030000c03f0000803e"
    "030000c03f0000803e030000c03f0000803e030000c03f0000803e"
)

# generated by gophertunnel b8bd735:
# &packet.ClientboundUpdateSoundData{ServerSoundHandle: 42, Stop: u, SetVolume: u, SetPitch: u, Fade: u,
#     SeekTo: u, Pause: u, Resume: u} with u := protocol.SoundDataUpdate{Type: protocol.SoundDataUpdateResume}
V2193_RESUME = bytes.fromhex("2a0000000000000006060606060606")

GOLDENS = [
    pytest.param(
        v1001.ClientboundUpdateSoundDataPacket(
            server_sound_handle=v1001.ServerSoundHandle(value=42), sound_event=v1001.SoundDataEvent.STOP
        ),
        V1001_STOP,
        id="v1001-stop",
    ),
    pytest.param(
        v2193.ClientboundUpdateSoundDataPacket(
            server_sound_handle=v2193.ServerSoundHandle(value=42),
            stop=v2193.SetVolume(volume=0.5),
            set_volume=v2193.SetVolume(volume=0.5),
            set_pitch=v2193.SetVolume(volume=0.5),
            fade=v2193.SetVolume(volume=0.5),
            seek_to=v2193.SetVolume(volume=0.5),
            pause=v2193.SetVolume(volume=0.5),
            resume=v2193.SetVolume(volume=0.5),
        ),
        V2193_VOLUME,
        id="v2193-set-volume",
    ),
    pytest.param(
        v2193.ClientboundUpdateSoundDataPacket(
            server_sound_handle=v2193.ServerSoundHandle(value=42),
            stop=v2193.Fade(duration=1.5, target_volume=0.25),
            set_volume=v2193.Fade(duration=1.5, target_volume=0.25),
            set_pitch=v2193.Fade(duration=1.5, target_volume=0.25),
            fade=v2193.Fade(duration=1.5, target_volume=0.25),
            seek_to=v2193.Fade(duration=1.5, target_volume=0.25),
            pause=v2193.Fade(duration=1.5, target_volume=0.25),
            resume=v2193.Fade(duration=1.5, target_volume=0.25),
        ),
        V2193_FADE,
        id="v2193-fade",
    ),
    pytest.param(
        v2193.ClientboundUpdateSoundDataPacket(
            server_sound_handle=v2193.ServerSoundHandle(value=42),
            stop=v2193.Resume(),
            set_volume=v2193.Resume(),
            set_pitch=v2193.Resume(),
            fade=v2193.Resume(),
            seek_to=v2193.Resume(),
            pause=v2193.Resume(),
            resume=v2193.Resume(),
        ),
        V2193_RESUME,
        id="v2193-resume",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_update_sound_data_is_packet_348(version):
    assert version.PACKETS[348] is version.ClientboundUpdateSoundDataPacket


def test_update_sound_data_is_absent_at_975():
    assert 348 not in v975.PACKETS


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_sound_data_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_sound_data_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_name_code_read_is_case_insensitive():
    assert v1001.ClientboundUpdateSoundDataPacket.from_bytes(
        bytes.fromhex("2a000000000000000453746f70")
    ) == v1001.ClientboundUpdateSoundDataPacket(
        server_sound_handle=v1001.ServerSoundHandle(value=42), sound_event=v1001.SoundDataEvent.STOP
    )


def test_2168_and_2193_share_one_body():
    assert v2168.ClientboundUpdateSoundDataPacket is v2193.ClientboundUpdateSoundDataPacket


def test_a_single_event_is_not_a_v2193_body():
    with pytest.raises(ValueError, match="at byte"):
        v2193.ClientboundUpdateSoundDataPacket.from_bytes(bytes.fromhex("2a0000000000000006"))


def test_a_v2193_body_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="at byte"):
        v1001.ClientboundUpdateSoundDataPacket.from_bytes(V2193_VOLUME)


@pytest.mark.parametrize(
    "event",
    [pytest.param(v2225.Resume(), id="resume"), pytest.param(v2225.Fade(duration=1.5, target_volume=0.25), id="fade")],
)
def test_v2225_round_trips_an_event_with_its_tag(event):
    packet = v2225.ClientboundUpdateSoundDataPacket(server_sound_handle=v2225.ServerSoundHandle(value=42), event=event)
    assert v2225.ClientboundUpdateSoundDataPacket.from_bytes(bytes(packet)) == packet


@pytest.mark.parametrize(
    ("event", "previous", "delta"),
    [
        pytest.param(v2225.Resume(), V2193_RESUME, -5, id="resume"),
        pytest.param(v2225.Fade(duration=1.5, target_volume=0.25), V2193_FADE, -53, id="fade"),
    ],
)
def test_v2225_writes_the_event_once_where_v2193_wrote_it_seven_times(event, previous, delta):
    packet = v2225.ClientboundUpdateSoundDataPacket(server_sound_handle=v2225.ServerSoundHandle(value=42), event=event)
    assert len(bytes(packet)) - len(previous) == delta


def test_a_v2193_body_does_not_decode_as_a_v2225_one():
    with pytest.raises(ValueError, match="at byte"):
        v2225.ClientboundUpdateSoundDataPacket.from_bytes(V2193_FADE)
